public override void ExecuteSkill()
{
	if (isUltimate)
	{
		if (!ultStarted)
		{
			ultStarted = true;
			ultStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.1f, 6);
			ultCounter = 0;
		}
		switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
		{
		case StopwatchState.Ready:
			spawnPosition = (Vector2)parent.attackOriginTrans.position + spawnOffset;
			if (ultCounter == 0)
			{
				perpendVec = Globals.GetPerpendicular(inputVector) * 0.5f;
				CreateFlameSlash(spawnPosition + perpendVec, inputVector, flipX: true);
				CreateFlameSlash(spawnPosition - perpendVec, inputVector);
			}
			else
			{
				for (int i = -ultCounter; i <= ultCounter; i++)
				{
					CreateFlameSlash(spawnPosition, Globals.GetRotatedCircleVector(24, i, inputVector));
				}
			}
			ultCounter++;
			parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animExecTime);
			break;
		case StopwatchState.Done:
			base.ExecuteSkill();
			parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animExecTime);
			break;

	return aimVector;
}

private void CreateProjectiles()
{
	currentPosition = parent.arrowSpawn.position;
	for (int i = 0; i < 5; i++)
	{
		currentVector = Globals.GetRotatedCircleVector(24, i - 2, aimVector);
		currProj = ChaosInst<Projectile>(projectilePrefab, currentPosition + currentVector, Globals.GetRotationQuaternion(currentVector));
		currProj.parentObject = parent.gameObject;
		currProj.parentEntity = parent;
		currProj.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		currProj.Show();
		currProj.attackBox.gameObject.SetActive(value: false);
		currProj.wallCollider.gameObject.SetActive(value: false);
		projArr[i] = currProj;
	}
}

private void HoldProjectiles()
{
	currentPosition = parent.arrowSpawn.position;
	for (int i = 0; i < 5; i++)
	{
		if (!(projArr[i] == null))
		{
			currentVector = Globals.GetRotatedCircleVector(24, i - 2, aimVector);
			currProj = projArr[i];
			currProj.transform.position = currentPosition + currentVector;
			currProj.RefreshFlightTime();
			currProj.transform.localEulerAngles = Globals.GetRotationVector(currentVector);
		}
	}
}

